// ===== DA CAMBIARE UNA VOLTA SOLA =====
const GA4_PROPRIETA = '000000000';                 // Google Analytics → Amministrazione → Dettagli proprietà → ID PROPRIETÀ (solo numeri)
const SEARCH_CONSOLE = 'sc-domain:freellmarena.com'; // se in Search Console la proprietà è «Prefisso URL», scrivi 'https://freellmarena.com/'
// =======================================
const oggi = new Date();
const inizio = new Date(Date.UTC(oggi.getUTCFullYear(), oggi.getUTCMonth() - 1, 1));
const fine = new Date(Date.UTC(oggi.getUTCFullYear(), oggi.getUTCMonth(), 0));
const g = (d) => d.toISOString().slice(0, 10);
return [{ json: { ga4: GA4_PROPRIETA, gsc: encodeURIComponent(SEARCH_CONSOLE), inizio: g(inizio), fine: g(fine), mese: inizio.toLocaleDateString('it-IT', { month: 'long', year: 'numeric', timeZone: 'UTC' }) } }];

const m = $('Mese scorso').first().json;
const ga = $('Visite (Google Analytics)').first().json;
const sc = $('Ricerche Google (Search Console)').first().json;
const ar = $('Voti della Free Arena').first().json;
const d = $input.first().json;
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const n = (x) => Number(x || 0).toLocaleString('it-IT');
const tot = ga?.totals?.[0]?.metricValues || [];
const pagine = (ga?.rows || []).map((r) => `<tr><td>${esc(r.dimensionValues[0].value)}</td><td style="text-align:right">${n(r.metricValues[0].value)}</td></tr>`).join('');
const ricerche = (sc?.rows || []).map((r) => `<tr><td>${esc(r.keys[0])}</td><td style="text-align:right">${n(r.clicks)}</td><td style="text-align:right">${n(r.impressions)}</td><td style="text-align:right">${(r.position || 0).toFixed(1)}</td></tr>`).join('');
const gratisChat = (d?.categorie || []).find((c) => c.id === 'chat')?.modelli.filter((x) => x.aperto || x.or?.gratis).length;
const tabella = (testa, righe) => righe ? `<table cellpadding="6" style="border-collapse:collapse;font-size:14px"><tr>${testa.map((t) => `<th align="left">${t}</th>`).join('')}</tr>${righe}</table>` : '<p><i>Nessun dato (controlla la credenziale in n8n).</i></p>';
const html = `<h2>FreeLLMArena, ${esc(m.mese)}</h2>
<h3>Visite</h3><p>Pagine viste: <b>${n(tot[0]?.value)}</b> · Utenti: <b>${n(tot[1]?.value)}</b></p>${tabella(['Pagina', 'Viste'], pagine)}
<h3>Ricerche Google</h3>${tabella(['Ricerca', 'Clic', 'Comparse', 'Posizione'], ricerche)}
<h3>Free Arena</h3><p>Voti totali: <b>${n(ar?.voti)}</b> (la classifica pubblica parte da ${n(ar?.soglia)} voti per modello).</p>
<h3>Sito</h3><p>Modelli gratis di chat in classifica: <b>${n(gratisChat)}</b> · Modelli nuovi seguiti: <b>${n(d?.nuovi?.length)}</b> · Dati aggiornati al ${esc(d?.aggiornato)}.</p>`;
return [{ json: { oggetto: `FreeLLMArena: report di ${m.mese}`, html } }];
